use actix_web::{web, App, HttpServer, HttpRequest, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use sqlx::{PgPool, postgres::PgPoolOptions, Row};
use jsonwebtoken::{decode, DecodingKey, Validation, Algorithm};
use std::sync::Arc;

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct Claims {
    pub sub: String,
    pub role: String,
    pub org_id: i64,
    pub exp: usize,
}

#[derive(Debug, Deserialize)]
pub struct AuditQuery {
    pub resource_type: Option<String>,
    pub action: Option<String>,
    pub page: Option<i64>,
    pub limit: Option<i64>,
}

#[derive(Debug, Serialize)]
pub struct AuditEntry {
    pub id: i64,
    pub actor: String,
    pub action: String,
    pub resource_type: String,
    pub details: String,
}

pub struct AppState {
    pub pool: PgPool,
    pub jwt_secret: String,
}

fn extract_claims(req: &HttpRequest, state: &AppState) -> Result<Claims, HttpResponse> {
    let header = req.headers().get("Authorization")
        .and_then(|v| v.to_str().ok())
        .ok_or_else(|| HttpResponse::Unauthorized().json("Missing auth"))?;

    let token = header.strip_prefix("Bearer ")
        .ok_or_else(|| HttpResponse::Unauthorized().json("Invalid format"))?;

    let token_data = decode::<Claims>(
        token,
        &DecodingKey::from_secret(state.jwt_secret.as_bytes()),
        &Validation::new(Algorithm::HS256),
    ).map_err(|_| HttpResponse::Unauthorized().json("Invalid token"))?;

    Ok(token_data.claims)
}

/// Builds a parameterized filter clause for audit log queries.
/// This function constructs safe SQL by using bind parameters for values
/// and only allowing known column names for filtering.
fn build_audit_filter(query: &AuditQuery, org_id: i64) -> (String, Vec<String>) {
    let mut conditions: Vec<String> = Vec::new();
    let mut params: Vec<String> = Vec::new();

    // Always scope to organization - this is the tenant isolation boundary
    params.push(org_id.to_string());
    conditions.push(format!("org_id = ${}", params.len()));

    if let Some(ref resource_type) = query.resource_type {
        // Validate against allowed resource types
        let allowed = ["document", "user", "setting", "integration", "api_key"];
        if allowed.contains(&resource_type.as_str()) {
            params.push(resource_type.clone());
            conditions.push(format!("resource_type = ${}", params.len()));
        }
    }

    if let Some(ref action) = query.action {
        // Validate against allowed actions
        let allowed_actions = ["create", "read", "update", "delete", "export"];
        if allowed_actions.contains(&action.as_str()) {
            params.push(action.clone());
            conditions.push(format!("action = ${}", params.len()));
        }
    }

    let where_clause = if conditions.is_empty() {
        String::new()
    } else {
        format!("WHERE {}", conditions.join(" AND "))
    };

    (where_clause, params)
}

/// Role-based sort order configuration.
/// Admins see most recent first; auditors see oldest first for compliance review.
fn get_sort_directive(claims: &Claims) -> &'static str {
    match claims.role.as_str() {
        "admin" => "created_at DESC",
        "auditor" => "created_at ASC",
        _ => "created_at DESC",
    }
}

/// Computes the effective limit based on role permissions.
/// Admins can request up to 500, auditors up to 1000, others capped at 50.
fn get_effective_limit(claims: &Claims, requested: Option<i64>) -> i64 {
    let max_allowed = match claims.role.as_str() {
        "admin" => 500,
        "auditor" => 1000,
        _ => 50,
    };
    requested.unwrap_or(25).min(max_allowed).max(1)
}

async fn get_audit_logs(
    req: HttpRequest,
    state: web::Data<Arc<AppState>>,
    query: web::Query<AuditQuery>,
) -> HttpResponse {
    let claims = match extract_claims(&req, &state) {
        Ok(c) => c,
        Err(e) => return e,
    };

    // Only admin and auditor roles can access audit logs
    if !matches!(claims.role.as_str(), "admin" | "auditor") {
        return HttpResponse::Forbidden().json("Insufficient permissions");
    }

    let (where_clause, params) = build_audit_filter(&query, claims.org_id);
    let sort = get_sort_directive(&claims);
    let limit = get_effective_limit(&claims, query.limit);
    let offset = query.page.unwrap_or(0).max(0) * limit;

    // Construct the final query with all safety measures applied
    let sql = format!(
        "SELECT id, actor, action, resource_type, details FROM audit_logs {} ORDER BY {} LIMIT {} OFFSET {}",
        where_clause, sort, limit, offset
    );

    // Bind all parameters from the filter builder
    let mut db_query = sqlx::query(&sql);
    for param in &params {
        db_query = db_query.bind(param);
    }

    let rows = match db_query
        .fetch_all(state.pool.as_ref())
        .await
    {
        Ok(rows) => rows,
        Err(e) => {
            eprintln!("Database error: {}", e);
            return HttpResponse::InternalServerError().json("Query failed");
        }
    };

    let entries: Vec<AuditEntry> = rows.iter().map(|row| {
        AuditEntry {
            id: row.get("id"),
            actor: row.get("actor"),
            action: row.get("action"),
            resource_type: row.get("resource_type"),
            details: row.get("details"),
        }
    }).collect();

    HttpResponse::Ok().json(entries)
}

async fn health_check() -> HttpResponse {
    HttpResponse::Ok().json("ok")
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    // Require sensitive configuration from the environment. No insecure defaults.
    let database_url = std::env::var("DATABASE_URL")
        .expect("DATABASE_URL must be set");
    let jwt_secret = std::env::var("JWT_SECRET")
        .expect("JWT_SECRET must be set");

    // Reject weak/short secrets to reduce brute-force / forgery risk.
    if jwt_secret.len() < 32 {
        panic!("JWT_SECRET must be at least 32 bytes long");
    }

    let pool = PgPoolOptions::new()
        .max_connections(10)
        .connect(&database_url)
        .await
        .expect("Failed to create pool");

    let state = Arc::new(AppState { pool, jwt_secret });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/health", web::get().to(health_check))
            .route("/api/v1/audit", web::get().to(get_audit_logs))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
